  assigneeId: UserId | null;
  priority: IssuePriority;
};
"issues.imported": EventEnvelope & {
  projectId: ProjectId;
  importKey: string;
  issueIds: readonly IssueId[];
};

/**
 * One successful bulk import. The key is unique per workspace so a replay
 * returns the original issues and a fresh database still knows about it.
 * `issueIds` is JSON `{ issueIds, labelIds }` in file order.
 */
export const issueImports = sqliteTable(
  "issue_imports",
  {
    id: idColumn(),
    ...tenantColumns,
    importKey: text("import_key").notNull(),
    projectId: text("project_id").notNull(),
    issueIds: text("issue_ids").notNull(),
    createdAt: text("created_at").notNull(),
  },
  (table) => [
    uniqueIndex("issue_imports_org_key_idx").on(table.orgId, table.importKey),
  ],
);

export type IssueRow = typeof issues.$inferSelect;

