      ? record.labelIds.map((entry) =>
          Array.isArray(entry)
            ? entry.filter((id): id is string => typeof id === "string")
            : [],
        )
      : issueIds.map(() => []);
    return {
      issueIds: issueIds as IssueId[],
      labelIds: labelIds as LabelId[][],
    };
  } catch {
    return { issueIds: [], labelIds: [] };
