/** A previous import of this key in this workspace, or null. */
export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<StoredIssueImport | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;
  const stored = parseStoredImport(row.issueIds);
  return {
    projectId: row.projectId as ProjectId,
    issueIds: stored.issueIds,
