  };
}

/** Loads issues in the given id order, overlaying the stored label order. */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
  labelIds: readonly (readonly LabelId[])[] = [],
): Promise<Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.id, [...issueIds]),
      ),
    )
    .all();

  const byId = new Map(rows.map((row) => [row.id, row]));
  const labelsByIssue = await listLabelsForIssues(orgId, issueIds);

  return issueIds.map((id, index) => {
    const row = byId.get(id);
    if (!row) throw new Error(`Issue ${id} not found`);
    const stored = labelIds[index];
    const resolved =
