    return toIssue(row, resolved);
  });
}

/**
 * Inserts every row of an import, the labels it had to create, and the replay
 * record, in one transaction. A key that landed between the caller's check
 * and this write returns the original record with `created: false`.
 */
export async function insertIssueImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  authorId: UserId;
  importKey: string;
  newLabelNames: readonly string[];
  existingLabelIds: ReadonlyMap<string, LabelId>;
  rows: readonly IssueImportWriteRow[];
}): Promise<IssueImportWriteResult> {
  const db = getDb();

  return db.transaction((tx) => {
    const already = tx
      .select()
      .from(issueImports)
      .where(
        and(
          eq(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (already) {
      const stored = parseStoredImport(already.issueIds);
      return {
        created: false,
        projectId: already.projectId as ProjectId,
        issueIds: stored.issueIds,
        labelIds: stored.labelIds,
      };
    }

    const stamp = toIsoTimestamp(new Date());
    const labelIdByName = new Map(input.existingLabelIds);

    for (const name of input.newLabelNames) {
      const labelId = newId() as LabelId;
      tx.insert(labels)
        .values({
          id: labelId,
          orgId: input.orgId,
          name,
          color: IMPORTED_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, labelId);
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          eq(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    const startNumber = (maxRow?.value ?? 0) + 1;

    const issueIds: IssueId[] = [];
    const labelIds: LabelId[][] = [];

    input.rows.forEach((row, index) => {
      const issueId = newId() as IssueId;
      const rowLabelIds = row.labelNames.map((name) => {
        const labelId = labelIdByName.get(name);
        if (!labelId) throw new Error(`Label "${name}" was not resolved`);
        return labelId;
      });

      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: input.projectId,
          number: startNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            rowLabelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }

      issueIds.push(issueId);
      labelIds.push(rowLabelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify({ issueIds, labelIds }),
        createdAt: stamp,
      })
      .run();

    return {
      created: true,
      projectId: input.projectId,
      issueIds,
      labelIds,
    };
  });
}

  return row?.value ?? 0;
}

/**
 * Email → user id for members who can still be assigned work: active and not
 * removed. Matching is the caller's job; emails are returned as stored.
 */
export async function listActiveMemberEmails(
  orgId: OrgId,
): Promise<readonly { userId: UserId; email: string }[]> {
  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return rows.map((row) => ({
    userId: row.userId as UserId,
    email: row.email,
  }));
}

