/**
 * Turns every row of an upload into an issue, in file order. The import is
 * refused before any write when the actor may not create issues, the project
 * is missing or archived, the batch would pass the per-project quota, or the
 * issue-creation rate allowance cannot cover every row. A key this workspace
 * has already imported returns that first result and writes nothing.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const prior = await issueRepo.findIssueImport(input.orgId, input.importKey);
  if (prior) {
    return replayImport(input.orgId, input.importKey, prior);
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const membersByEmail = new Map<string, (typeof actor)["userId"]>();
  for (const member of await memberRepo.listActiveMemberEmails(input.orgId)) {
    membersByEmail.set(member.email.toLowerCase(), member.userId);
  }

  const existingLabels = await labelRepo.listLabels(input.orgId);
  const existingLabelIds = new Map(
    existingLabels.map((label) => [label.name, label.id]),
  );

  const newLabelNames: string[] = [];
  const seenNewLabels = new Set<string>();
  for (const row of input.rows) {
    for (const name of row.labels) {
      if (existingLabelIds.has(name) || seenNewLabels.has(name)) continue;
      seenNewLabels.add(name);
      newLabelNames.push(name);
    }
  }

  const written = await issueRepo.insertIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    authorId: actor.userId,
    importKey: input.importKey,
    newLabelNames,
    existingLabelIds,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (membersByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: uniqueLabelNames(row.labels),
    })),
  });

  const issues = await issueRepo.findIssuesByIds(
    input.orgId,
    written.issueIds,
    written.labelIds,
  );

  if (!written.created) {
    return {
      importKey: input.importKey,
      projectId: written.projectId,
      issues,
      replayed: true,
    };
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: written.projectId,
    importKey: input.importKey,
    issueIds: written.issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: written.projectId,
    issues,
    replayed: false,
  };
}

async function replayImport(
  orgId: OrgId,
  importKey: string,
  prior: {
    projectId: ProjectId;
    issueIds: readonly IssueId[];
    labelIds: readonly (readonly LabelId[])[];
  },
): Promise<IssueImportResult> {
  const issues = await issueRepo.findIssuesByIds(
    orgId,
    prior.issueIds,
    prior.labelIds,
  );
  return {
    importKey,
    projectId: prior.projectId,
    issues,
    replayed: true,
  };
}

function uniqueLabelNames(names: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const name of names) {
