import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, notifications, webhookDeliveries } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { importIssues } from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import { count, eq } from "drizzle-orm";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("import");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

function rows() {
  return importIssuesSchema.parse({
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    importKey: "upload-key-1",
    rows: [
      {
        title: "First imported",
        description: "alpha body",
        status: "in_progress",
        priority: "high",
        assigneeEmail: "ADMIN@import.test",
        labels: ["Bug", "Bug", "NewLabel"],
        dueAt: "2026-12-01T00:00:00.000Z",
      },
      {
        title: "Second imported",
        assigneeEmail: "missing@nope.test",
        labels: ["NewLabel", "bug"],
      },
    ],
  });
}

describe("importIssues", () => {
  it("imports a batch in order and replays the key", async () => {
    resetRateLimits();
    await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        eventTypes: ["issue.created", "issue.assigned", "issue.updated"],
      },
      "secret",
    );

    const outsider = await userRepo.insertUser({
      email: "outsider@nope.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    await memberRepo.insertMember(tenant.org.id, outsider.id, "member", null);
    const membership = await memberRepo.findMember(tenant.org.id, outsider.id);
    if (!membership) throw new Error("member missing");
    await memberRepo.archiveMember(tenant.org.id, membership.id);

    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "Bug",
      color: "#112233",
      description: "kept",
    });

    const other = await createTenant("importother");
    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "NewLabel",
      color: "#abcdef",
      description: "foreign",
    });

    const seenCreated: unknown[] = [];
    const seenImported: unknown[] = [];
    const { subscribe } = await import("@/lib/event-bus");
    const offCreated = subscribe("issue.created", (payload) => {
      seenCreated.push(payload);
    });
    const offImported = subscribe("issues.imported", (payload) => {
      seenImported.push(payload);
    });

    const input = rows();
    input.rows[1] = {
      ...input.rows[1],
      assigneeEmail: outsider.email,
    };

    const first = await importIssues(tenant.actors.member, input);

    expect(first.replayed).toBe(false);
    expect(first.issues.map((issue) => issue.title)).toEqual([
      "First imported",
      "Second imported",
    ]);
    expect(first.issues.map((issue) => issue.number)).toEqual([1, 2]);
    expect(first.issues[0]).toMatchObject({
      description: "alpha body",
      status: "in_progress",
      priority: "high",
      assigneeId: tenant.userIds.admin,
      authorId: tenant.actors.member.userId,
      parentId: null,
      estimate: null,
      dueAt: "2026-12-01T00:00:00.000Z",
      startedAt: null,
      completedAt: null,
    });
    expect(first.issues[1]?.assigneeId).toBeNull();

    const labels = await labelRepo.listLabels(tenant.org.id);
    const bug = labels.find((label) => label.name === "Bug");
    const created = labels.find((label) => label.name === "NewLabel");
    const lower = labels.find((label) => label.name === "bug");
    expect(bug?.color).toBe("#112233");
    expect(bug?.description).toBe("kept");
    expect(created?.color).toBe("#94a3b8");
    expect(created?.description).toBeNull();
    expect(lower?.color).toBe("#94a3b8");
    expect(labels.filter((label) => label.name === "NewLabel")).toHaveLength(1);
    expect(first.issues[0]?.labelIds).toEqual([bug?.id, created?.id]);
    expect(first.issues[1]?.labelIds).toEqual([created?.id, lower?.id]);

    expect(seenCreated).toHaveLength(0);
    expect(seenImported).toHaveLength(1);
    expect(seenImported[0]).toMatchObject({
      actorId: tenant.actors.member.userId,
      projectId: tenant.project.id,
      importKey: "upload-key-1",
      issueIds: first.issues.map((issue) => issue.id),
    });

    const usage = await usageRepo.getUsage(tenant.org.id);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.issuesUsed).toBe(2);
    expect(recounted.issuesUsed).toBe(2);

    const activity = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "project",
      tenant.project.id,
    );
    const imported = activity.filter((event) => event.action === "issues.imported");
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      actorId: tenant.actors.member.userId,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "upload-key-1" },
    });
    const perIssue = activity.filter((event) => event.action === "issue.created");
    expect(perIssue).toHaveLength(0);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "alpha body",
      kinds: ["issue"],
      limit: 10,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.subjectId)).toContain(first.issues[0]?.id);

    const notes = getDb()
      .select({ value: count() })
      .from(notifications)
      .where(eq(notifications.orgId, tenant.org.id))
      .get();
    expect(notes?.value).toBe(0);

    const deliveries = getDb()
      .select({ value: count() })
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .get();
    expect(deliveries?.value).toBe(0);

    const again = await importIssues(tenant.actors.member, {
      ...input,
      rows: [{ ...input.rows[0], title: "Changed title that must be ignored" }],
    });
    expect(again.replayed).toBe(true);
    expect(again.issues.map((issue) => issue.id)).toEqual(
      first.issues.map((issue) => issue.id),
    );
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(2);
    expect(seenImported).toHaveLength(1);

    const otherResult = await importIssues(other.actors.member, {
      ...input,
      orgId: other.org.id,
      projectId: other.project.id,
    });
    expect(otherResult.replayed).toBe(false);
    expect(otherResult.issues).toHaveLength(2);
    expect(otherResult.projectId).toBe(other.project.id);

    const next = await importIssues(tenant.actors.member, {
      ...input,
      importKey: "upload-key-2",
      rows: [{ title: "Third wave" }],
    });
    expect(next.issues[0]?.number).toBe(3);

    const createdAfter = await (
      await import("@/server/services/issue-service")
    ).createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After import" }),
    );
    expect(createdAfter.number).toBe(4);

    offCreated();
    offImported();
  });

  it("refuses without writing when access, quota, or rate limit fails", async () => {
    resetRateLimits();
    const fresh = await createTenant("importguard", "free");

    await expect(
      importIssues(tenant.actors.member, {
        ...rows(),
        orgId: fresh.org.id,
        projectId: fresh.project.id,
        importKey: "guard-key-01",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      importIssues(fresh.actors.member, {
        ...rows(),
        orgId: fresh.org.id,
        projectId: tenant.project.id,
        importKey: "guard-key-01",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      importIssues(fresh.actors.viewer, {
        orgId: fresh.org.id,
        projectId: fresh.project.id,
        importKey: "guard-key-01",
        rows: [{ title: "Nope viewer" }],
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await projectRepo.archiveProject(fresh.org.id, fresh.project.id);
    await expect(
      importIssues(fresh.actors.member, {
        orgId: fresh.org.id,
        projectId: fresh.project.id,
        importKey: "guard-key-01",
        rows: [{ title: "Archived project" }],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const quota = await createTenant("importquota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, quota.project.id, { title: `Seed ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }

    await expect(
      importIssues(quota.actors.member, {
        orgId: quota.org.id,
        projectId: quota.project.id,
        importKey: "quota-key-01",
        rows: [{ title: "One fits" }, { title: "Two does not" }],
      }),
    ).rejects.toThrow(/allows no more issues/);
    expect(await issueRepo.countIssues(quota.org.id, quota.project.id)).toBe(99);

    const one = await importIssues(quota.actors.member, {
      orgId: quota.org.id,
      projectId: quota.project.id,
      importKey: "quota-key-01",
      rows: [{ title: "One fits" }],
    });
    expect(one.replayed).toBe(false);
    expect(one.issues[0]?.number).toBe(100);

    await expect(
      importIssues(quota.actors.member, {
        orgId: quota.org.id,
        projectId: quota.project.id,
        importKey: "quota-key-02",
        rows: [{ title: "Past the limit" }],
      }),
    ).rejects.toThrow(/allows no more issues/);

    const limited = await createTenant("importrate", "free");
    for (let i = 0; i < 60; i += 1) {
      const verdict = await consumeRateLimit(limited.org.id, "issue:create");
      expect(verdict.allowed).toBe(true);
    }
    await expect(
      importIssues(limited.actors.member, {
        orgId: limited.org.id,
        projectId: limited.project.id,
        importKey: "rate-key-001",
        rows: [{ title: "Rate blocked" }],
      }),
    ).rejects.toThrow(/rate limit/i);
    expect(
      await issueRepo.countIssues(limited.org.id, limited.project.id),
    ).toBe(0);

    resetRateLimits();
    const later = await importIssues(limited.actors.member, {
      orgId: limited.org.id,
      projectId: limited.project.id,
      importKey: "rate-key-001",
      rows: [{ title: "Rate blocked" }, { title: "Second row" }],
    });
    expect(later.replayed).toBe(false);
    expect(later.issues).toHaveLength(2);
  });
});

